The final annotation format is:
{
    "video_path": str,
    "video_begin": int,
    "video_end": int,
    "video_duration": int,
    "active_speaker": {
        speaker_name: "",
        "persona": list[str],
    },
    "metadata": {
        "tag": str,
        "dataset_name": str,
    },
    "annotations": [
        # solo commentary and commentary from active speaker in multi-speaker discussion
        {
            "role": assistant,
            "speaker": str,
            "start": int,
            "end": int,
            "text": str,
        },
        # commentary from other speakers in multi-speaker discussion
        {
            "role": user,
            "speaker": str,
            "start": int,
            "end": int,
            "text": str,
        },
        # user query in Q&A
        {
            "role": user,
            "speaker": 'user',
            "start": int,
            "end": int,
            "query": str,
        },
    ]
}
